'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var setReadWriteAccessor = require( '@stdlib/utils/define-nonenumerable-read-write-accessor' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var plotBase = require( '@stdlib/plot/unicode/base/lib' );
var defineProperty = require( '@stdlib/utils/define-property' );
var objectKeys = require( '@stdlib/utils/keys' );
var inherit = require( '@stdlib/utils/inherit' );
var isObject = require( '@stdlib/assert/is-plain-object' );
var pick = require( '@stdlib/utils/pick' );
var format = require( '@stdlib/string/format' );
var setBackgroundColor = require( './props/background-color/set.js' );
var getBackgroundColor = require( './props/background-color/get.js' );
var setForegroundColor = require( './props/foreground-color/set.js' );
var getForegroundColor = require( './props/foreground-color/get.js' );
var setCategoriesFormat = require( './props/categaries-format/set.js' );
var getCategoriesFormat = require( './props/categaries-format/get.js' );
var setBarWidth = require( './props/bar-width/set.js' );
var getBarWidth = require( './props/bar-width/get.js' );
var setBarGap = require( './props/bar-gap/set.js' );
var getBarGap = require( './props/bar-gap/get.js' );
var setBarsColor = require( './props/bars-color/set.js' );
var getBarsColor = require( './props/bars-color/get.js' );
var setBarsPerLabel = require( './props/bars-per-label/set.js' );
var getBarsPerLabel = require( './props/bars-per-label/get.js' );
var setXAxisFormat = require( './props/x-axis-format/set.js' );
var getXAxisFormat = require( './props/x-axis-format/get.js' );
var setGlyph = require( './props/glyph/set.js' );
var getGlyph = require( './props/glyph/get.js' );
var setData = require( './props/data/set.js' );
var getData = require( './props/data/get.js' );
var render = require( './render.js' );
var defaults = require( './default.js' );


// VARIABLES //

var debug = logger( 'table:unicode:main' );

// List of private properties (note: keep in alphabetical order):
var PRIVATE_PROPS = [
	'_data',
	'_autoRender',
	'_categariesOrder',
	'_categoriesFormat',
	'_xAxisFormat'
];

// List of options properties (note: keep in alphabetical order):
var OPTIONS_PROPS = [
	'xAxisData',
	'glyph',
	'foregroundColor',
	'backgroundColor',
	'autoRender',
	'data',
	'categoriesOrder',
	'categoriesFormat',
	'xAxisFormat',
	'barGap',
	'barWidth',
	'barsColor',
	'barsPerLabel'
];


// FUNCTIONS //

/**
* Initializes private instance properties.
*
* @private
* @param {BarPlot} barPlot - barPlot instance
* @param {Object} defaults - default property values
* @returns {PlotBase} plotBase instance
*/
function initializePrivateProperties( barPlot, defaults ) { // eslint-disable-line id-length
	var i;

	for ( i = 0; i < PRIVATE_PROPS.length; i++ ) {
		defineProperty( barPlot, PRIVATE_PROPS[ i ], {
			'configurable': false,
			'enumerable': false,
			'writable': true,
			'value': defaults[ PRIVATE_PROPS[ i ].substring( 1 ) ] || null
		});
	}
	return plotBase;
}


// MAIN //

/**
* Unicode bar chart constructore.
*
* @private
* @constructor
* @throws {TypeError} data argument must be an object, an array of objects, an array of arrays, or a two-dimensional ndarray
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @returns {BarPlot} barPlot instance
*/
function BarPlot() {
	var options;
	var nargs;
	var opts;
	var keys;
	var self;
	var key;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof BarPlot ) ) {
		if ( nargs === 0 ) {
			return new BarPlot();
		}
		return new BarPlot( arguments[ 0 ] );
	}
	defineProperty( this, '_baseConstructor', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': plotBase()
	});
	defineProperty( this, '_xAxisDataObj', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': {
			'data': [],
			'autoAdjectment': false,
			'scaleType': 'linear',
			'format': '%s',
			'start': 'auto'
		}
	});
	defineProperty( this, '_categariesObj', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': {
			'data': [],
			'autoAdjectment': false,
			'order': 'original',
			'format': '%s'
		}
	});
	defineProperty( this, '_barObj', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': {
			'width': 5,
			'gap': 3,
			'colors': [],
			'num': 1
		}
	});

	// Initialize private instance properties:
	initializePrivateProperties( this, defaults() );
	this._quiet = false;

	// Resolve input arguments...
	if ( nargs === 0 ) {
		options = {};
	} else {
		options = arguments[ 0 ];
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
	}
	// Extract provided options while ignoring any extraneous/unsupported options properties:
	opts = pick( options, OPTIONS_PROPS );

	debug( 'Creating an instance with the following configuration: %s.', JSON.stringify( opts ) );

	// Validate provided options by assigning values to barPlot properties...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		key = keys[ i ];
		this[ key ] = opts[ key ];
	}
	// Add event listeners:
	this.on( 'change', onChange );
	this.on( 'render', onRender );
	self = this;
	return this;

	/**
	* Callback invoked upon receiving a `change` event.
	*
	* @private
	*/
	function onChange() {
		/* eslint-disable no-underscore-dangle */
		debug( 'Received a change event.' );
		if ( self._autoRender ) {
			self.render();
		}
	}

	/**
	* Callback invoked upon receiving a `render` event.
	*
	* @private
	* @param {string} table - rendered table
	*/
	function onRender() {
		debug( 'Received a render event.' );
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( BarPlot, EventEmitter );

/**
* @name backgroundColor
* @memberof PlotBase.prototype
* @type {string}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'backgroundColor', getBackgroundColor, setBackgroundColor );

/**
* @name forgroundColor
* @memberof PlotBase.prototype
* @type {string}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'forgroundColor', getForegroundColor, setForegroundColor );

/**
* @name barGap
* @memberof PlotBase.prototype
* @type {number}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'barGap', getBarGap, setBarGap );

/**
* @name barWidth
* @memberof PlotBase.prototype
* @type {number}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'barWidth', getBarWidth, setBarWidth );

/**
* @name barColors
* @memberof PlotBase.prototype
* @type {number}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'barsColor', getBarsColor, setBarsColor );

/**
* @name barsPerLabel
* @memberof PlotBase.prototype
* @type {number}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'barsPerLabel', getBarsPerLabel, setBarsPerLabel );

/**
* @name xAxisFormat
* @memberof PlotBase.prototype
* @type {string}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'xAxisFormat', getXAxisFormat, setXAxisFormat );

/**
* @name categoriesFormat
* @memberof PlotBase.prototype
* @type {string}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'categoriesFormat', getCategoriesFormat, setCategoriesFormat );

/**
* @name glyph
* @memberof PlotBase.prototype
* @type {string}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'glyph', getGlyph, setGlyph );

/**
* @name data
* @memberof PlotBase.prototype
* @type {Array}
* @throws {TypeError} must be valid background color code string
*/
setReadWriteAccessor( BarPlot.prototype, 'data', getData, setData );

/**
* Renders a plot.
*
* @name render
* @memberof PlotBase.prototype
* @type {Function}
* @returns {string} rendered table
*/
setReadOnly( BarPlot.prototype, 'render', render );


// EXPORTS //

module.exports = BarPlot;
